class LoggingFilter @Inject() (implicit ec: ExecutionContext) extends EssentialFilter {
  def apply(next: EssentialAction): EssentialAction = new EssentialAction {
    def apply(request: RequestHeader) = {
      val start = System.currentTimeMillis                       // pre
      next(request).map { result =>                              // the action
        result.withHeaders("Request-Time" -> (System.currentTimeMillis - start).toString)  // post
      }
    }
  }
}
